D)*1)%11=0 THEN ('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9))||((10-((CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),1,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),1,1)::int END)*1+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),2,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),2,1)::int END)*3+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),3,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),3,1)::int END)*1+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),4,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),4,1)::int END)*3+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),5,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),5,1)::int END)*1+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),6,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),6,1)::int END)*3+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),7,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),7,1)::int END)*1+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),8,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),8,1)::int END)*3+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),9,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),9,1)::int END)*1+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),10,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),10,1)::int END)*3+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),11,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),11,1)::int END)*1+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),12,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),12,1)::int END)*3)%10)%10)::text END END)
 AND proof->>'locale'=e.locale AND nullif(e.locale,'') IS NOT NULL AND proof->>'edition_title'=e.title AND nullif(btrim(e.title),'') IS NOT NULL
 AND proof->>'reason' IN (E'children_picture',E'children_only',E'graded_reader',E'abridged',E'non_reading_product',E'wrong_locale',E'wrong_work',E'editorial_exclusion')
 AND (proof->>'reason' NOT IN (E'wrong_work',E'editorial_exclusion') OR (jsonb_typeof(proof->'content_id')='string' AND nullif(proof->>'content_id','')=e.content_id))
 AND char_length(btrim(coalesce(proof->>'explanation','')))>=20
 AND coalesce(proof->>'source_url','') ~ '^https://[A-Za-z0-9.-]*[A-Za-z][A-Za-z0-9-]*[.]?(:[0-9]{1,5})?([/?#][^[:space:]]*)?$'
 AND (CASE WHEN proof->>'source_url' ~ '^https://[A-Za-z0-9.-]+:[0-9]{1,5}([/?#]|$)' THEN substring(proof->>'source_url' from '^https://[^/?#:]+:([0-9]+)')::int ELSE 0 END)<=65535
 AND lower(split_part(split_part(substring(proof->>'source_url' from '^https://([^/?#]+)'),':',1),'@',1)) !~ '(^|[.])openlibrary[.]org[.]?$')),false)
   AND public.book_translator_identity(e.sources->'translators') IS NOT DISTINCT FROM translators
 ) THEN RAISE EXCEPTION 'Same original or translation already has a representative edition; attach products to it'; END IF;
 RETURN new;
END;
$policy$;
DROP TRIGGER IF EXISTS guard_figure_book_edition_policy ON public.figure_book_editions;
CREATE TRIGGER guard_figure_book_edition_policy BEFORE INSERT OR UPDATE OF id,content_id,locale,title,creator,description,isbn,publisher,thumbnail_url,release_date,edition_kind,text_scope,sort_order,verified,sources ON public.figure_book_editions
FOR EACH ROW EXECUTE FUNCTION public.guard_figure_book_edition_policy();
create or replace function public.seed_figure_book_editions()
returns trigger
language plpgsql
set search_path to 'pg_catalog'
as $function$
begin
  -- ISBN 없는 공급자 판본도 인물 관계가 추가될 때마다 복제하지 않는다.
  perform 1 from public.contents where id = new.content_id for no key update;
  insert into public.figure_book_editions (
    content_id, locale, title, creator, description, isbn, publisher,
    thumbnail_url, release_date, edition_kind, text_scope, sort_order,
    verified, sources
  )
  select
    locale.content_id, locale.locale,
    coalesce(nullif(btrim(locale.sources->>'edition_title'), ''),
      nullif(btrim(locale.title), ''), content.external_id, content.id),
    nullif(btrim(locale.creator), ''), locale.description,
    nullif(btrim(locale.isbn), ''), nullif(btrim(locale.publisher), ''),
    locale.thumbnail_url,
    case when content.release_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}'
      then left(content.release_date, 10)::date else null end,
    case when content.metadata #>> '{fictionSource,editionKind}'
      in (E'full',E'retelling',E'adaptation',E'selection',E'volume')
      then content.metadata #>> '{fictionSource,editionKind}' else null end,
    nullif(content.metadata #>> '{fictionSource,textScope}', ''),
    0, locale.verified, locale.sources
  from public.contents as content
  join public.content_locales as locale on locale.content_id = content.id
  where content.id = new.content_id and content.type = 'BOOK'
    and NOT public.book_nonstart_work_volume(locale.title,content.metadata->'figureBook',content.metadata #>> '{fictionSource,textScope}')
    and coalesce(content.metadata #>> '{fictionSource,editionKind}', '') <> 'abridged'
    and coalesce(content.metadata #>> '{figureBook,editionKind}', '') <> 'abridged'
    and NOT (locale.locale='ko' AND coalesce(locale.title,'') ~ E'[（(]\\s*(?:영문판|영문원서|영어\\s*원서)\\s*(?:[）)]|[-–])')
    and coalesce(locale.title, '') !~* E'축약(?:본|판)|축역|요약본|원서\\s*발췌|[（(]발췌[）)]|천줄읽기|\\yabridg(?:ed|ement|ment)\\y|^(?:인스타리드\\s|Instaread\\y|Outlines and Highlights for\\y)'
    and coalesce(locale.title, '') !~* E'\\y(?:penguin\\s+(?:longman\\s+)?readers|(?:oxford\\s+)?bookworms)\\y'
    and NOT coalesce(locale.sources->>'provider_edition_isbn'=locale.isbn AND (coalesce(locale.sources->>'provider_edition_title','') ~* E'축약(?:본|판)|축역|요약본|원서\\s*발췌|[（(]발췌[）)]|천줄읽기|\\yabridg(?:ed|ement|ment)\\y|^(?:인스타리드\\s|Instaread\\y|Outlines and Highlights for\\y)' OR coalesce(locale.sources->>'provider_edition_title','') ~* E'\\y(?:penguin\\s+(?:longman\\s+)?readers|(?:oxford\\s+)?bookworms)\\y'),false)
    and NOT coalesce(locale.locale='ko' AND locale.sources->>'provider_edition_isbn'=locale.isbn AND coalesce(locale.sources->>'provider_edition_title','') ~ E'[（(]\\s*(?:영문판|영문원서|영어\\s*원서)\\s*(?:[）)]|[-–])',false)
    and coalesce(locale.sources->>'provider_scope_description',locale.sources #>> '{provider_metadata,contents}','') !~* E'세계명작다이제스트\\s*시리즈|\\ySheet\\s+eBook\\y|\\d+(?:\\.\\d+)?\\s*%\\s*(?:를\\s*)?발췌(?:로|해|하여)\\s*번역|반복되는\\s*부분을\\s*덜어내[^.。\\n]{0,40}축약(?:했|하였)|한\\s*품도\\s*빠뜨리지\\s*않고\\s*그\\s*요지를\\s*간추렸'
    and coalesce(content.metadata #>> '{fictionSource,textScope}', '') !~* E'^(?:abridg(?:ed|ement|ment)|selection\\/abridged|축약(?:본|판)|축역(?:본|판)|요약본|발췌·요약\\s*단권|two-percent-original-extract|selection\\/approximately-\\d+-percent)(?=$|[\\s/:;,])'
    and coalesce(content.metadata #>> '{fictionSource,textScope}', '') !~* E'^(?:(?:[a-z]+[-/])*(?:volume|part)[-/\\s]+(?:book\\/)?(?:0*(?:[2-9]|\\d{2,3})|II|III|IV|V|VI|VII|VIII|IX|X)(?=$|[-\\s/:])|『[^』]+』\\s*제\\s*0*(?:[2-9]|\\d{2,3})권;\\s*(?:전체\\s*)?시리즈\\s*중\\s*해당\\s*권의\\s*본문|(?:한국어\\s*(?:번역|원작)\\s*분권|원작\\s*분권)\\s*(?:하권|0*(?:[2-9]|\\d{2,3})권)(?=$|[\\s(])|제\\s*0*(?:[2-9]|\\d{2,3})권\\s)|\\yvolume\\s+0*(?:[2-9]|\\d{2,3})\\s+of\\s+\\d{1,3}\\y'
    and not (locale.locale = 'en' and coalesce(locale.sources->>'primary', '') = 'kakao_book')
    and not (coalesce(locale.sources->>'primary', '') = 'none'
      and coalesce(locale.sources->>'title', '') in ('translated', 'romanized', 'original', 'display_only'))
    and not (nullif(btrim(locale.isbn), '') is null
      and coalesce(locale.sources->>'title', '') = 'kakao_title_search'
      and coalesce(locale.sources->>'series_source_url', '') !~ E'^https:\\/\\/(?:m\\.)?search\\.daum\\.net\\/search\\?.*bookId=\\d+')
    and (nullif(btrim(locale.isbn), '') is not null
      or locale.sources->>'primary' in ('kakao_book', 'openlibrary'))
    and not exists (
      select 1 from public.figure_book_editions edition
      where edition.content_id = locale.content_id and edition.locale = locale.locale
        and ((NOT coalesce(content.metadata #>> '{figureBook,originalLanguage}'=locale.locale
            AND content.metadata #>> '{figureBook,identityEvidence}' ~ '^https://',false)
          and (public.book_translator_identity(locale.sources->'translators') IS NULL
            or public.book_translator_identity(edition.sources->'translators') IS NULL))
          or public.book_translator_identity(edition.sources->'translators') IS NOT DISTINCT FROM public.book_translator_identity(locale.sources->'translators'))
    )
    and not exists (
      select 1 from public.figure_book_editions edition
      where edition.content_id = locale.content_id and edition.locale = locale.locale
        and edition.isbn is not distinct from nullif(btrim(locale.isbn), '')
        and (edition.isbn is not null or edition.title = coalesce(
          nullif(btrim(locale.sources->>'edition_title'), ''),
          nullif(btrim(locale.title), ''), content.external_id, content.id))
    )
  on conflict (content_id, locale, isbn) where isbn is not null do nothing;
  return new;
end;
$function$;
COMMIT;
